import {calculateEstimate} from './estimate.mjs';
const money=value=>new Intl.NumberFormat('ru-RU').format(value)+' ₸';
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const root=document.querySelector('#estimate-lines'),picker=document.querySelector('#equipment'),send=document.querySelector('#send-estimate');
const storageKey='mba-equipment-estimate-v2';let catalog=[],rows=[],restored=false;
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(rows));}catch{}}
function announce(message){document.querySelector('#estimate-status').textContent=message;}
function render(){
 root.innerHTML=rows.length?rows.map((row,index)=>{
 const item=catalog.find(i=>i.id===row.id);
 return `<article class="estimate-line" data-id="${escape(row.id)}"><div class="estimate-equipment"><img src="${escape(item.image)}" alt="" width="80" height="70"><div><span class="line-index">${String(index+1).padStart(2,'0')} / ${escape(item.label)}</span><h3>${escape(item.name)}</h3><small>${item.price==null?'Стоимость уточним':money(item.price)+' / '+(item.period==='day'?'день':'месяц')}</small></div><button type="button" class="remove-line" data-remove="${escape(row.id)}" aria-label="Убрать ${escape(item.name)}">×</button></div><div class="line-controls"><label>Количество машин<div class="estimate-stepper"><button type="button" data-step="-1" data-field="units" aria-label="Уменьшить количество: ${escape(item.name)}">−</button><input aria-label="Количество: ${escape(item.name)}" data-field="units" type="number" min="1" max="100" step="1" value="${row.units}" required><button type="button" data-step="1" data-field="units" aria-label="Увеличить количество: ${escape(item.name)}">+</button></div></label><label>Срок, ${item.period==='day'?'дней':'месяцев'}<div class="estimate-stepper"><button type="button" data-step="-1" data-field="duration" aria-label="Уменьшить срок: ${escape(item.name)}">−</button><input aria-label="Срок: ${escape(item.name)}" data-field="duration" type="number" min="1" max="120" step="1" value="${row.duration}" required><button type="button" data-step="1" data-field="duration" aria-label="Увеличить срок: ${escape(item.name)}">+</button></div></label><div class="line-sum"><span>За позицию</span><strong data-line-total></strong></div></div></article>`;
 }).join(''):'<div class="estimate-empty"><span>↗</span><h3>Соберите технику под ваш объект</h3><p>Добавьте первую машину из списка выше или из каталога.</p></div>';
 root.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.src='assets/site-work.jpg';},{once:true}));update();
}
function update(){
 const result=calculateEstimate(catalog,rows);
 result.details.forEach(row=>{const total=root.querySelector(`[data-id="${row.id}"] [data-line-total]`);if(total)total.textContent=!row.valid?'Проверьте значения':row.total==null?'По запросу':money(row.total);});
 document.querySelector('#estimate-count').textContent=String(rows.length).padStart(2,'0');
 document.querySelector('#machine-count').textContent=result.units;
 document.querySelector('#estimate-total-label').textContent=result.onRequest===rows.length&&rows.length?'Стоимость аренды':result.onRequest?'По известным тарифам':'Ориентировочный итог';
 document.querySelector('#total').textContent=!rows.length?'0 ₸':!result.valid?'Проверьте значения':result.onRequest===rows.length?'По запросу':money(result.knownTotal);
 document.querySelector('#request-note').textContent=result.onRequest===rows.length&&rows.length?'Стоимость всех позиций уточнит менеджер.':result.onRequest?`Ещё ${result.onRequest} поз. — по запросу. Их стоимость не включена в сумму.`:'';
 send.setAttribute('aria-disabled',String(!result.valid));send.classList.toggle('disabled',!result.valid);
 if(result.valid){const lines=result.details.map((row,index)=>`${index+1}. ${row.item.name} — ${row.units} ед. × ${row.duration} ${row.item.period==='day'?'дн.':'мес.'} — ${row.total==null?'цена по запросу':money(row.total)}`);const total=result.onRequest?`Сумма по известным тарифам: ${money(result.knownTotal)}. Стоимость ${result.onRequest} поз. нужно уточнить.`:`Предварительный итог: ${money(result.knownTotal)}.`;send.href='https://wa.me/77788275160?text='+encodeURIComponent('Здравствуйте! Нужна техника для объекта:\n\n'+lines.join('\n')+'\n\n'+total+'\nПодскажите наличие, подачу и окончательные условия аренды.');}else send.removeAttribute('href');
 persist();
}
function add(id){if(!catalog.some(i=>i.id===id))return;const row=rows.find(i=>i.id===id);if(row){row.units=Math.min(100,(row.units||1)+1);}else rows.push({id,units:1,duration:1});render();announce(`${catalog.find(i=>i.id===id).name} — ${row?'количество увеличено':'добавлено в смету'}`);}
document.querySelector('#add-equipment').addEventListener('click',()=>add(picker.value));
root.addEventListener('click',event=>{const remove=event.target.closest('[data-remove]');if(remove){rows=rows.filter(row=>row.id!==remove.dataset.remove);render();announce('Позиция удалена из сметы');document.querySelector('#add-equipment').focus();return;}const button=event.target.closest('[data-step]');if(!button)return;const line=button.closest('[data-id]'),row=rows.find(row=>row.id===line.dataset.id),field=button.dataset.field;row[field]=Math.max(1,Math.min(field==='units'?100:120,(row[field]||1)+Number(button.dataset.step)));line.querySelector(`input[data-field="${field}"]`).value=row[field];update();});
root.addEventListener('input',event=>{if(!event.target.matches('input[data-field]'))return;const row=rows.find(row=>row.id===event.target.closest('[data-id]').dataset.id);row[event.target.dataset.field]=Number(event.target.value);update();});
send.addEventListener('click',event=>{if(send.getAttribute('aria-disabled')==='true'){event.preventDefault();root.querySelector(':invalid')?.reportValidity();announce(rows.length?'Укажите целые количества от 1 до 100 и сроки от 1 до 120.':'Сначала добавьте технику в смету.');}});
document.addEventListener('click',event=>{const button=event.target.closest('[data-add-to-estimate]');if(!button)return;add(button.dataset.addToEstimate);button.textContent='Добавлено ✓';setTimeout(()=>button.textContent='В расчёт +',1400);});
export function initCalculator(data){catalog=data;picker.innerHTML=catalog.map(i=>`<option value="${escape(i.id)}">${escape(i.name)}${i.id==='zoomlion'?' · 25 т':''}</option>`).join('');try{const saved=JSON.parse(localStorage.getItem(storageKey));if(Array.isArray(saved)){restored=true;rows=saved.filter(row=>row&&catalog.some(i=>i.id===row.id)&&Number.isInteger(row.units)&&row.units>0&&row.units<=100&&Number.isInteger(row.duration)&&row.duration>0&&row.duration<=120).filter((row,index,list)=>list.findIndex(i=>i.id===row.id)===index).map(({id,units,duration})=>({id,units,duration}));}}catch{}if(!restored)rows=[{id:catalog[0].id,units:1,duration:1}];picker.disabled=false;document.querySelector('#add-equipment').disabled=false;render();}
